<?php $u=rtrim($_ENV['APP_URL']??'','/'); use App\Services\AccessService; $manage=AccessService::can('academico.oferta.gestionar'); ?>
<div class="page-head"><div><span class="eyebrow">ACADÉMICO · PLANIFICACIÓN</span><h1>Períodos y oferta académica</h1><p>Define el calendario académico y publica la oferta de cada carrera, malla, sede y modalidad.</p></div><?php if($manage):?><div><a class="btn" href="<?=$u?>/admin/academico/periodos/form">Nuevo período</a> <a class="btn" href="<?=$u?>/admin/academico/oferta/form">Nueva oferta</a></div><?php endif;?></div>
