<section class="card"><div class="section-head"><div><span class="eyebrow">02</span><h2>Oferta académica</h2></div></div><div class="table-scroll"><table><thead><tr><th>Período</th><th>Carrera / malla</th><th>Sede / modalidad</th><th>Estado</th><th>Secciones</th><th></th></tr></thead><tbody><?php foreach($offers as $x):?><tr><td><?=htmlspecialchars($x['periodo'])?></td><td><strong><?=htmlspecialchars($x['carrera'])?></strong><br><small><?=htmlspecialchars($x['malla_codigo'].' · '.$x['malla'])?></small></td><td><?=htmlspecialchars($x['sede']?:'Todas')?> · <?=htmlspecialchars($x['modalidad']?:'Sin especificar')?></td><td><span class="badge <?=$x['permite_matricula']?'success':'muted'?>"><?=htmlspecialchars($x['estado'])?></span></td><td><?=$x['secciones']?></td><td><a href="<?=$u?>/admin/academico/oferta/ver?id=<?=$x['id']?>">Abrir</a><?php if($manage):?> · <a href="<?=$u?>/admin/academico/oferta/form?id=<?=$x['id']?>">Editar</a><?php endif;?></td></tr><?php endforeach;?><?php if(!$offers):?><tr><td colspan="6">Todavía no hay ofertas académicas.</td></tr><?php endif;?></tbody></table></div></section>
